(function(){'use strict';const button=$('#projectMenuButton'),menu=$('#projectMenu');menu.hidden=true;function close(){menu.hidden=true;button.setAttribute('aria-expanded','false')}button.onclick=()=>{menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden))};for(const id of ['openBtn','saveBtn']){const fn=$('#'+id).onclick;$('#'+id).onclick=e=>{close();fn(e)}}$('#newProjectBtn').onclick=()=>{close();confirmDialog('Start a new project?','Save your current project first if you want a downloadable copy. You can also undo this change.',()=>{stop();remember();project={version:1,name:'Untitled story',fps:24,images:{},characters:{},frames:[{name:'First frame',duration:.2,tween:false,easing:'smooth',background:'#f3eddf',light:1,camera:{x:960,y:540,zoom:1,rotation:0},objects:[]}]};fi=0;selected=[];playTime=0;setTool('select');changed();renderLibrary()})};$('#resumeProjectBtn').onclick=()=>{close();if(!window.lastSavedProject)return;confirmDialog('Resume saved project?','This replaces the demo or the currently open project. Save your current edits first if needed.',async()=>{try{stop();remember();const restored=validateProject(clone(window.lastSavedProject));await M.ready(restored);project=restored;fi=0;selected=[];playTime=0;setTool('select');refreshUI();renderLibrary();toast('Saved project restored.')}catch(e){toast(e.message)}})};document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('.project-menu'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});})();
